<script setup lang="ts">
import {ref,computed,onMounted} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import {api} from './session'
import {useTableWidths} from './tableWidths'
import SupplierInput from './SupplierInput.vue'
const props=defineProps<{context:any}>(),emit=defineEmits<{created:[],close:[]}>()
const widths=useTableWidths('ProcurementCreate')
const isPlan=computed(()=>props.context.kind==='plans'),title=computed(()=>isPlan.value?'新增采购计划':'新增采购单')
const stores=ref<string[]>([]),warehouses=ref<any[]>([]),buyers=ref<any[]>([])
const busy=ref(false),loading=ref(false),error=ref(''),rows=ref<any[]>([]),products=ref<any[]>([]),finished=ref(false)
const routes=[['UK_air','英国空派'],['UK_truck','英国卡航'],['UK_sea','英国海运'],['DE_air','德国空派'],['DE_truck','德国卡航'],['DE_sea','德国海运']]
function id(){const b=crypto.getRandomValues(new Uint8Array(16));b[6]=(b[6]!&15)|64;b[8]=(b[8]!&63)|128;const s=Array.from(b,v=>v.toString(16).padStart(2,'0')).join('');return `${s.slice(0,8)}-${s.slice(8,12)}-${s.slice(12,16)}-${s.slice(16,20)}-${s.slice(20)}`}
let requestId=id(),fingerprint='',searchSequence=0
function add(){if(rows.value.length>=200)return;rows.value.push({key:id(),product_id:null,warehouse_id:props.context.warehouse_id||warehouses.value[0]?.id,store:props.context.store||(isPlan.value?stores.value[0]||'':''),quantities:Object.fromEntries(routes.map(([k])=>[k,0])),expected_date:'',unit_cost:0,supplier:'',extra_cost:0,buyer:'',note:''})}
async function search(q=''){const n=++searchSequence;try{const result=await api('/products?'+new URLSearchParams({q,page_size:'50'}));if(n===searchSequence){const selected=products.value.filter(p=>rows.value.some(r=>r.product_id===p.id));products.value=[...new Map([...selected,...result.rows].map(p=>[p.id,p])).values()]}}catch(e){error.value=(e as Error).message}}
function productChanged(row:any){const p=products.value.find(p=>p.id===row.product_id);if(p){row.code=p.code;row.name=p.name;row.unit_cost=Number(p.cost_cny||0);row.supplier=p.primary_supplier||''}}
function quantity(row:any){return routes.reduce((n,[key])=>n+Number(row.quantities[key!]||0),0)}
const total=computed(()=>rows.value.reduce((n,r)=>n+quantity(r),0))
const price=computed(()=>rows.value.reduce((n,r)=>n+Math.round((quantity(r)*Number(r.unit_cost||0)+Number(r.extra_cost||0))*10000),0)/10000)
const invalid=computed(()=>!rows.value.length||rows.value.some(r=>!r.product_id||!r.warehouse_id||quantity(r)<=0||routes.some(([k])=>!Number.isInteger(r.quantities[k!]??0)||(r.quantities[k!]||0)<0||(r.quantities[k!]||0)>10000000)||(isPlan.value?!r.store:!r.expected_date||r.unit_cost==null)))
async function load(){loading.value=true;error.value='';try{const d=await api('/procurement/options');stores.value=d.stores;warehouses.value=d.warehouses;buyers.value=d.buyers||[];if(!rows.value.length)add();await search()}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
async function save(){if(invalid.value||busy.value)return;error.value='';const values=rows.value.map(r=>isPlan.value?{product_id:r.product_id,warehouse_id:r.warehouse_id,store:r.store,buyer:r.buyer||'',note:r.note||'',routes:routes.filter(([k])=>r.quantities[k!]>0).map(([k])=>({country:k!.split('_')[0],channel:k!.split('_')[1],quantity:r.quantities[k!]}))}:{product_id:r.product_id,warehouse_id:r.warehouse_id,store:r.store||'',quantity:quantity(r),quantities:Object.fromEntries(routes.map(([k])=>[k,r.quantities[k!]||0])),expected_date:r.expected_date,unit_cost:r.unit_cost,supplier:r.supplier||'',extra_cost:r.extra_cost||0});const next=JSON.stringify(values);if(fingerprint&&fingerprint!==next)requestId=id();fingerprint=next;busy.value=true;try{const d=await api(isPlan.value?'/procurement/plan-batches/bulk':'/procurement/flow/orders',{request_id:requestId,...(isPlan.value?{items:values}:{rows:values})});finished.value=true;ElMessage.success(isPlan.value?`已新增 ${d.created} 个采购计划`:`已新增 ${new Set(d.orders.map((o:any)=>o.number)).size} 张采购单`);emit('created')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function canLeave(){if(busy.value)return false;if(finished.value||!rows.value.length)return true;try{await ElMessageBox.confirm('关闭后将放弃本页未保存的内容。','关闭新增页面',{confirmButtonText:'关闭',cancelButtonText:'继续编辑'});return true}catch{return false}}
defineExpose({canLeave})
onMounted(load)
</script>
<template><section class="procurement-create" v-loading="loading"><header><h2>{{title}}</h2><div><el-button type="primary" :disabled="busy||loading||rows.length>=200" @click="add">新增商品</el-button><el-button :disabled="busy" @click="emit('close')">返回采购管理</el-button></div></header><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-button v-if="!rows.length&&!loading" @click="load">重新加载</el-button><el-form :disabled="busy"><el-table border :data="rows" row-key="key"  data-width-key="ProcurementCreate/lines" @header-dragend="(w:number,_o:number,c:any)=>widths.resize('lines',w,c)" @header-contextmenu="(c:any,e:MouseEvent)=>widths.resetColumn('lines',c,e)">
<el-table-column column-key="product" label="标品编码（必填）" :width="widths.width('lines','product',280)"><template #default="{row}"><el-select v-model="row.product_id" filterable remote :remote-method="search" placeholder="搜索标品编码" @change="productChanged(row)"><el-option v-for="p in products" :key="p.id" :value="p.id" :label="p.code+' · '+p.name"/></el-select></template></el-table-column>
<el-table-column column-key="warehouse" label="仓库（必填）" :width="widths.width('lines','warehouse',150)"><template #default="{row}"><el-select v-model="row.warehouse_id"><el-option v-for="w in warehouses" :key="w.id" :value="w.id" :label="w.name"/></el-select></template></el-table-column>
<el-table-column column-key="store" :label="isPlan?'店铺（必填）':'店铺（选填）'" :width="widths.width('lines','store',145)"><template #default="{row}"><el-select v-model="row.store" @change="row.buyer=''" clearable :placeholder="isPlan?'请选择店铺':'可稍后指定'"><el-option v-for="s in stores" :key="s" :value="s" :label="s"/></el-select></template></el-table-column>
<el-table-column column-key="quantity" label="采购数量" :width="widths.width('lines','quantity',120)" align="center"><template #default="{row}"><span>{{quantity(row)}}</span></template></el-table-column>
<el-table-column v-for="[key,label] in routes" :key="key" :column-key="key" :label="label" :width="widths.width('lines',key!,115)" align="center"><template #default="{row}"><el-input-number v-model="row.quantities[key!]" :aria-label="label+' 第'+(rows.indexOf(row)+1)+'行'" :min="0" :max="10000000" :precision="0" :controls="false" style="width:100%"/></template></el-table-column>
<el-table-column v-if="!isPlan" column-key="date" label="预计到货时间" :width="widths.width('lines','date',170)"><template #default="{row}"><el-date-picker v-model="row.expected_date" type="date" value-format="YYYY-MM-DD" style="width:100%"/></template></el-table-column>
<el-table-column v-if="!isPlan" column-key="supplier" label="供应商" :width="widths.width('lines','supplier',220)"><template #default="{row}"><SupplierInput v-model="row.supplier"/></template></el-table-column>
<el-table-column v-if="!isPlan" column-key="cost" label="采购单价 (¥)" :width="widths.width('lines','cost',145)" align="center"><template #default="{row}"><el-input-number v-model="row.unit_cost" :min="0" :precision="4" :controls="false" style="width:100%"/></template></el-table-column>
<el-table-column v-if="!isPlan" column-key="extra" label="其他费用 (¥)" :width="widths.width('lines','extra',145)" align="center"><template #default="{row}"><el-input-number v-model="row.extra_cost" :min="0" :precision="4" :controls="false" style="width:100%"/></template></el-table-column>
<el-table-column v-if="isPlan" label="采购员" width="150"><template #default="{row}"><el-select v-model="row.buyer" clearable><el-option v-for="b in buyers.filter(b=>b.is_admin||(b.stores||[]).includes(row.store))" :key="b.username" :value="b.username" :label="b.username"/></el-select></template></el-table-column><el-table-column v-if="isPlan" label="备注" width="220"><template #default="{row}"><el-input v-model="row.note" maxlength="1000"/></template></el-table-column><el-table-column column-key="actions" label="操作" fixed="right" width="80"><template #default="{row}"><el-button link type="danger" @click="rows.splice(rows.indexOf(row),1)">删除</el-button></template></el-table-column>
</el-table></el-form><p>采购数量自动汇总六个渠道的数量，请直接填写各渠道数量。支持一次添加多个商品。</p><p v-if="!isPlan">供应商和单价默认读取商品信息，可继续修改；同供应商、同预计到货日期合并为一张采购单。</p><footer><span>共 {{rows.length}} 条商品 · {{total}} 件 <b v-if="!isPlan">　总价 ¥{{price.toFixed(2)}}</b></span><div><el-button :disabled="busy" @click="emit('close')">取消</el-button><el-button type="primary" :disabled="invalid||loading||finished" :loading="busy" @click="save">{{isPlan?'保存采购计划':'保存采购单'}}</el-button></div></footer></section></template>
<style scoped>.procurement-create{padding:24px;background:white;min-height:0}header,footer{display:flex;justify-content:space-between;align-items:center;gap:20px}header{margin-bottom:24px}h2{margin:0;font-size:22px}footer{position:sticky;bottom:0;background:white;padding:20px 0;border-top:1px solid #e4ece7;z-index:5}p{color:#788e82;font-size:13px;line-height:1.7}:deep(.el-table .cell){padding:0 8px;text-overflow:clip}</style>
